{
  "components": [
    {
      "type": "claim",
      "quote": "It is possible to gain access to official SFOE documents under the Freedom of Information Act.",
      "gist": "Access to SFOE official documents is allowed under the Freedom of Information Act."
    },
    {
      "type": "condition",
      "quote": "This applies to documents produced after 1 July 2006.",
      "gist": "The access rule applies only to documents created after 1 July 2006."
    },
    {
      "type": "claim",
      "quote": "There is no complicated procedure for requesting access – a written request is not required.",
      "gist": "No complicated procedure is needed to request access; a written request is not required."
    },
    {
      "type": "obligation",
      "quote": "You just need to provide enough information for us to identify the document requested.",
      "gist": "Requesters must provide sufficient information to identify the requested document."
    },
    {
      "type": "other",
      "quote": "Give as much information as possible: the date the document was created, the title or references, the exact subject domain and the time period it refers to are all useful.",
      "gist": "Provide details like creation date, title, subject domain, and time period to help identify the document."
    }
  ]
}
